,CAAC,GAAG,EAAE,CAAA;AAAA,IAChC,KAAA,EAAO,QAAA,CAAS,KAAA,CAAM,CAAC,GAAG,EAAE;AAAA,GAC9B;AACF;AASO,SAAS,eAAe,IAAA,EAAyC;AACtE,EAAA,MAAM,KAAA,GAAQ,IAAA,CAAK,KAAA,CAAM,WAAW,CAAA;AACpC,EAAA,IAAI,CAAC,OAAO,OAAO,IAAA;AACnB,EAAA,OAAO;AAAA,IACL,MAAA,EAAQ,QAAA,CAAS,KAAA,CAAM,CAAC,GAAG,EAAE;AAAA,GAC/B;AACF;AAKO,SAAS,cAAc,IAAA,EAAuB;AACnD,EAAA,OAAO,aAAA,CAAc,KAAK,IAAI,CAAA;AAChC;AAKO,SAAS,YAAY,IAAA,EAAuB;AACjD,EAAA,OAAO,WAAA,CAAY,KAAK,IAAI,CAAA;AAC9B;AAWO,SAAS,UAAA,CAAW,GAAW,CAAA,EAAoB;AAExD,EAAA,MAAM,QAAA,GAAW,iBAAiB,CAAC,CAAA;AACnC,EAAA,MAAM,QAAA,GAAW,iBAAiB,CAAC,CAAA;AACnC,EAAA,IAAI,YAAY,QAAA,EAAU;AACxB,IAAA,OAAO,SAAS,SAAA,KAAc,QAAA,CAAS,SAAA,IAAa,QAAA,CAAS,UAAU,QAAA,CAAS,KAAA;AAAA,EAClF;AAGA,EAAA,MAAM,MAAA,GAAS,eAAe,CAAC,CAAA;AAC/B,EAAA,MAAM,MAAA,GAAS,eAAe,CAAC,CAAA;AAC/B,EAAA,IAAI,UAAU,MAAA,EAAQ;AACpB,IAAA,OAAO,MAAA,CAAO,WAAW,MAAA,CAAO,MAAA;AAAA,EAClC;AAGA,EAAA,OAAO,CAAA,KAAM,CAAA;AACf;AA4LO,SAAS,iBAAiB,QAAA,EAAkD;AACjF,EAAA,OAAO,QAAA,CAAS,OAAA,CAAQ,IAAA,CAAK,CAAC,CAAA,KAAM,EAAE,WAAW,CAAA,KAAM,QAAA,CAAS,mBAAmB,CAAC,CAAA;AACtF","file":"index.cjs","sourcesContent":["export interface IcebergErrorResponse {
  error: {
    message: string
    type: string
    code: number
    stack?: string[]
  }
}

export class IcebergError extends Error {
  readonly status: number
  readonly icebergType?: string
  readonly icebergCode?: number
  readonly details?: unknown
  readonly isCommitStateUnknown: boolean

  constructor(
    message: string,
    opts: {
      status: number
      icebergType?: string
      icebergCode?: number
      details?: unknown
    }
  ) {
    super(message)
    this.name = 'IcebergError'
    this.status = opts.status
    this.icebergType = opts.icebergType
    this.icebergCode = opts.icebergCode
    this.details = opts.details

    // Detect CommitStateUnknownException (500, 502, 504 during table commits)
    this.isCommitStateUnknown =
      opts.icebergType === 'CommitStateUnknownException' ||
      ([500, 502, 504].includes(opts.status) && opts.icebergType?.includes('CommitState') === true)
  }

  /**
   * Returns true if the error is a 404 Not Found error.
   */
  isNotFound(): boolean {
    return this.status === 404
  }

  /**
   * Returns true if the error is a 409 Conflict error.
   */
  isConflict(): boolean {
    return this.status === 409
  }

  /**
   * Returns true if the error is a 419 Authentication Timeout error.
   */
  isAuthenticationTimeout(): boolean {
    return this.status === 419
  }
}
","export function buildUrl(
  baseUrl: string,
  path: string,
  query?: Record<string, string | undefined>
): string {
  const url = new URL(path, baseUrl)

  if (query) {
    for (const [key, value] of Object.entries(query)) {
      if (value !== undefined) {
        url.searchParams.set(key, value)
      }
    }
  }

  return url.toString()
}
